import{_ as t,c as i,o as a,ag as s}from"./chunks/framework.ARG558ZT.js";const u=JSON.parse('{"title":"Testing Node.js Applications — practice","description":"","frontmatter":{},"headers":[],"relativePath":"practice/node-js/module-04-testing.md","filePath":"practice/node-js/module-04-testing.md"}'),o={name:"practice/node-js/module-04-testing.md"};function l(r,e,n,c,d,h){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="testing-node-js-applications-—-practice" tabindex="-1">Testing Node.js Applications — practice <a class="header-anchor" href="#testing-node-js-applications-—-practice" aria-label="Permalink to “Testing Node.js Applications — practice”">​</a></h1><p><strong>Learner status: still required.</strong> These tasks were separated from the textbook; no completion is credited.</p><p><a href="./../../node-js/module-04-testing.html">Textbook explanation</a> · <a href="./">Node.js practice map</a></p><h3 id="diagnostic-exercise" tabindex="-1">Diagnostic exercise <a class="header-anchor" href="#diagnostic-exercise" aria-label="Permalink to “Diagnostic exercise”">​</a></h3><p>Take a deliberately flaky API suite and fix it without adding sleeps.</p><p>Include these defects:</p><ul><li>fixed port collisions;</li><li>shared database records;</li><li>a spy that is not restored;</li><li>dependence on the current timezone;</li><li>an unclosed server;</li><li>a missing <code>await</code> on a rejected promise.</li></ul><p>Document the evidence that identified each cause.</p><hr><h2 id="_17-final-review-checklist" tabindex="-1">17. Final review checklist <a class="header-anchor" href="#_17-final-review-checklist" aria-label="Permalink to “17. Final review checklist”">​</a></h2><p>You should be able to explain and demonstrate each item:</p><h3 id="advanced-confidence" tabindex="-1">Advanced confidence <a class="header-anchor" href="#advanced-confidence" aria-label="Permalink to “Advanced confidence”">​</a></h3><ul><li>Reuse contract tests across compatible implementations.</li><li>Describe when a property expresses behavior better than selected examples.</li><li>Test shared-state invariants under concurrent operations.</li><li>Diagnose order, parallelism, time, environment, and open-handle flakiness.</li><li>Replace sleeps with deterministic completion signals.</li><li>Use mutation testing selectively to assess assertion strength.</li></ul><h3 id="strategy" tabindex="-1">Strategy <a class="header-anchor" href="#strategy" aria-label="Permalink to “Strategy”">​</a></h3><ul><li>The Testing Pyramid emphasizes unit tests; the Testing Trophy emphasizes integration tests and static analysis.</li><li>Both are heuristics, not fixed test ratios.</li><li>Unit tests isolate small behaviors; integration tests connect selected real components; E2E tests use the external system boundary.</li><li>The smallest test boundary that detects the target failure usually gives the best feedback.</li><li>Static analysis complements runtime tests.</li></ul><h3 id="jest" tabindex="-1">Jest <a class="header-anchor" href="#jest" aria-label="Permalink to “Jest”">​</a></h3><ul><li><code>test()</code> and <code>it()</code> define tests; <code>describe()</code> groups behavior and hook scope.</li><li><code>beforeAll()</code>/<code>afterAll()</code> run once per scope; <code>beforeEach()</code>/<code>afterEach()</code> surround each test.</li><li>Every asynchronous test and hook must return or await its work.</li><li><code>toBe()</code> checks primitive equality/object identity; <code>toEqual()</code> checks structural values.</li><li>Synchronous exceptions use <code>expect(() =&gt; action()).toThrow()</code>.</li><li>Promise failures use <code>await expect(action()).rejects.toThrow()</code>.</li><li>Parameterized tests reduce duplication when cases share one behavior.</li></ul><h3 id="test-doubles" tabindex="-1">Test doubles <a class="header-anchor" href="#test-doubles" aria-label="Permalink to “Test doubles”">​</a></h3><ul><li><code>jest.fn()</code> creates a controllable, inspectable function.</li><li><code>jest.spyOn()</code> observes a real object method and calls it by default until mocked.</li><li><code>jest.mock()</code> replaces a module according to the project&#39;s module system.</li><li><code>clearAllMocks()</code> clears history, <code>resetAllMocks()</code> also removes implementations, and <code>restoreAllMocks()</code> restores supported replaced properties/spies.</li><li>Unit tests replace external boundaries but should not mock the behavior under test.</li><li>Over-mocking can let incompatible real components pass independently.</li></ul><h3 id="test-levels" tabindex="-1">Test levels <a class="header-anchor" href="#test-levels" aria-label="Permalink to “Test levels”">​</a></h3><ul><li>Unit tests cover happy paths, errors, boundaries, and collaborator outcomes deterministically.</li><li>Integration tests explicitly define which components are real.</li><li>Integration infrastructure and data must be isolated and cleaned up.</li><li>Supertest can test a Node.js app without binding a fixed public port.</li><li>API tests assert status, body contract, headers, authorization, and important side effects.</li><li>Nock mocks outbound HTTP; it is not itself an E2E runner.</li><li>Uncontrolled public services should not be a normal CI dependency.</li></ul><h3 id="coverage-and-reliability" tabindex="-1">Coverage and reliability <a class="header-anchor" href="#coverage-and-reliability" aria-label="Permalink to “Coverage and reliability”">​</a></h3><ul><li>Coverage measures execution, not correctness or assertion quality.</li><li>Statement, branch, function, and line coverage answer different questions.</li><li><code>collectCoverageFrom</code> ensures never-imported source appears in reports.</li><li>Coverage thresholds can fail CI but should reflect meaningful risk.</li><li>Coverage reporters serve different consumers: text/HTML for people and LCOV/Cobertura for tooling.</li><li>Tests must control time, randomness, environment, files, network, database state, and identifiers when those affect results.</li><li>Open handles must be closed so Jest terminates.</li><li>Sleeps should be replaced with completion signals or fake timers.</li><li>Tests must pass alone, together, in different orders, and under expected parallelism.</li></ul><p><strong>Practice acceptance:</strong> implement the registration change in a separate practice project, map every requirement to at least one meaningful test, deliberately remove the stored hash and observe REG-2 fail, then remove the unique constraint and observe the concurrency protection fail. Restore the implementation and run the real applicable Autocode commands without altering src/tests. Record a short review with one genuine finding and its corrected verification. Writing this matrix does not complete learner practice.</p>',24)])])}const m=t(o,[["render",l]]);export{u as __pageData,m as default};
